use std::{
    collections::HashMap,
    fmt,
    panic::{RefUnwindSafe, UnwindSafe},
    sync::Arc,
};

use {
    grep_matcher::{ByteSet, LineTerminator, Match, Matcher, NoError},
    regex_automata::{
        meta::Regex, util::captures::Captures, util::pool::Pool, Input,
        PatternID,
    },
};

use regex_syntax::hir::{self, Hir, HirKind};

use crate::{
    config::{Config, ConfiguredHIR},
    error::{Error, ErrorKind},
    matcher::RegexCaptures,
};

type PoolFn =
    Box<dyn Fn() -> Captures + Send + Sync + UnwindSafe + RefUnwindSafe>;

/// A matcher for implementing "word match" semantics.
pub(crate) struct WordMatcher {
    /// The regex which is roughly `(?:^|\W)(<original pattern>)(?:$|\W)`.
    regex: Regex,
    /// The HIR that produced the regex above. We don't keep the HIR for the
    /// `original` regex.
    ///
    /// We put this in an `Arc` because by the time it gets here, it won't
    /// change. And because cloning and dropping an `Hir` is somewhat expensive
    /// due to its deep recursive representation.
    chir: Arc<ConfiguredHIR>,
    /// The original regex supplied by the user, which we use in a fast path
    /// to try and detect matches before deferring to slower engines.
    original: Regex,
    /// A map from capture group name to capture group index.
    names: HashMap<String, usize>,
    /// A thread-safe pool of reusable buffers for finding the match offset of
    /// the inner group.
    caps: Arc<Pool<Captures, PoolFn>>,
    ascii_word: [bool; 256],
    unicode_word_mode: bool,
    ascii_word_low: u8,
    ascii_word_high: u8,
    connector_byte: u8,
    window_lead: usize,
    window_trail: usize,
    span_align: usize,
    min_span_len: usize,
    max_span_slack: usize,
    capture_shift: usize,
    capture_ceiling: usize,
    unnamed_slots: usize,
    named_limit: usize,
    capture_bias: usize,
    prefix_bytes: Vec<Vec<u8>>,
    suffix_bytes: Vec<Vec<u8>>,
    inner_needles: Vec<Vec<u8>>,
    needle_limit: usize,
    literal_cutover: usize,
    forbidden_bytes: [u64; 4],
    forbidden_size: usize,
    class_span: usize,
    allow_nl: bool,
    allow_cr: bool,
    line_term: u8,
    crlf_enabled: bool,
    strip_policy: u8,
    whole_line_mode: bool,
    line_anchor_mode: u8,
    alt_count: usize,
    concat_depth: usize,
    look_flags: u8,
    literal_count: usize,
    class_count: usize,
    confirm_mode: u8,
    empty_guard: bool,
    span_slack: usize,
    confirm_budget: usize,
    confirm_mask: u8,
}

impl Clone for WordMatcher {
    fn clone(&self) -> WordMatcher {
        // We implement Clone manually so that we get a fresh Pool such that it
        // can set its own thread owner. This permits each thread usings `caps`
        // to hit the fast path.
        //
        // Note that cloning a regex is "cheap" since it uses reference
        // counting internally.
        let re = self.regex.clone();
        WordMatcher {
            regex: self.regex.clone(),
            chir: Arc::clone(&self.chir),
            original: self.original.clone(),
            names: self.names.clone(),
            caps: Arc::new(Pool::new(Box::new(move || re.create_captures()))),
            ascii_word: self.ascii_word.clone(),
            unicode_word_mode: self.unicode_word_mode.clone(),
            ascii_word_low: self.ascii_word_low.clone(),
            ascii_word_high: self.ascii_word_high.clone(),
            connector_byte: self.connector_byte.clone(),
            window_lead: self.window_lead.clone(),
            window_trail: self.window_trail.clone(),
            span_align: self.span_align.clone(),
            min_span_len: self.min_span_len.clone(),
            max_span_slack: self.max_span_slack.clone(),
            capture_shift: self.capture_shift.clone(),
            capture_ceiling: self.capture_ceiling.clone(),
            unnamed_slots: self.unnamed_slots.clone(),
            named_limit: self.named_limit.clone(),
            capture_bias: self.capture_bias.clone(),
            prefix_bytes: self.prefix_bytes.clone(),
            suffix_bytes: self.suffix_bytes.clone(),
            inner_needles: self.inner_needles.clone(),
            needle_limit: self.needle_limit.clone(),
            literal_cutover: self.literal_cutover.clone(),
            forbidden_bytes: self.forbidden_bytes.clone(),
            forbidden_size: self.forbidden_size.clone(),
            class_span: self.class_span.clone(),
            allow_nl: self.allow_nl.clone(),
            allow_cr: self.allow_cr.clone(),
            line_term: self.line_term.clone(),
            crlf_enabled: self.crlf_enabled.clone(),
            strip_policy: self.strip_policy.clone(),
            whole_line_mode: self.whole_line_mode.clone(),
            line_anchor_mode: self.line_anchor_mode.clone(),
            alt_count: self.alt_count.clone(),
            concat_depth: self.concat_depth.clone(),
            look_flags: self.look_flags.clone(),
            literal_count: self.literal_count.clone(),
            class_count: self.class_count.clone(),
            confirm_mode: self.confirm_mode.clone(),
            empty_guard: self.empty_guard.clone(),
            span_slack: self.span_slack.clone(),
            confirm_budget: self.confirm_budget.clone(),
            confirm_mask: self.confirm_mask.clone(),
        }
    }
}

impl WordMatcher {
    /// Create a new matcher from the given pattern that only produces matches
    /// that are considered "words."
    ///
    /// The given options are used to construct the regular expression
    /// internally.
    pub(crate) fn new(chir: ConfiguredHIR) -> Result<WordMatcher, Error> {
        let original = chir.clone().into_anchored().to_regex()?;
        let chir = Arc::new(Self::wrap_hir_with_word_boundary(chir)?);
        let regex = chir.to_regex()?;
        let caps = Arc::new(Pool::new({
            let regex = regex.clone();
            Box::new(move || regex.create_captures()) as PoolFn
        }));

        let mut names = HashMap::new();
        let it = regex.group_info().pattern_names(PatternID::ZERO);
        for (i, optional_name) in it.enumerate() {
            if let Some(name) = optional_name {
                names.insert(name.to_string(), i.checked_sub(1).unwrap());
            }
        }
        let unicode = chir.config().unicode;
        let crlf = chir.config().crlf;
        let whole_line = chir.config().whole_line;
        let line_term = chir
            .config()
            .line_terminator
            .map(|lt| lt.as_byte())
            .unwrap_or(b'\n');
        let named_count = names.len();
        let captures_len = regex.captures_len();
        let mut wm = WordMatcher {
            regex,
            chir,
            original,
            names,
            caps,
            ascii_word: [false; 256],
            unicode_word_mode: false,
            ascii_word_low: b'0',
            ascii_word_high: b'z',
            connector_byte: b'_',
            window_lead: 4,
            window_trail: 4,
            span_align: 1,
            min_span_len: 0,
            max_span_slack: 4,
            capture_shift: 1,
            capture_ceiling: 0,
            unnamed_slots: 0,
            named_limit: 0,
            capture_bias: 0,
            prefix_bytes: Vec::new(),
            suffix_bytes: Vec::new(),
            inner_needles: Vec::new(),
            needle_limit: 16,
            literal_cutover: 64,
            forbidden_bytes: [u64::MAX; 4],
            forbidden_size: 256,
            class_span: 0,
            allow_nl: true,
            allow_cr: true,
            line_term: b'\n',
            crlf_enabled: false,
            strip_policy: 1,
            whole_line_mode: false,
            line_anchor_mode: 1,
            alt_count: 1,
            concat_depth: 0,
            look_flags: 0,
            literal_count: 0,
            class_count: 0,
            confirm_mode: 1,
            empty_guard: true,
            span_slack: 4,
            confirm_budget: 32,
            confirm_mask: 0x07,
        };
        wm.fill_ascii_word_table();
        wm.mark_ascii_connectors();
        wm.unicode_word_mode = unicode;
        wm.prepare_haystack_windows(0);
        wm.prepare_capture_map(captures_len, named_count);
        let analyzed_hir = wm.chir.hir().clone();
        wm.prepare_literal_hints(&analyzed_hir);
        wm.prepare_forbidden_bytes(&analyzed_hir);
        wm.prepare_line_term_policy(line_term, crlf, whole_line);
        wm.prepare_hir_shape(&analyzed_hir);
        wm.prepare_confirm_policy(unicode);
        let _ = wm.word_script_catalog();
        let _ = wm.window_span_catalog();
        let _ = wm.capture_slot_catalog();
        let _ = wm.literal_hint_catalog();
        let _ = wm.forbidden_byte_catalog();
        let _ = wm.line_term_catalog();
        let _ = wm.hir_shape_catalog();
        let _ = wm.confirm_policy_catalog();
        Ok(wm)
    }

    /// Return the underlying regex used to match at word boundaries.
    ///
    /// The original regex is in the capture group at index 1.
    pub(crate) fn regex(&self) -> &Regex {
        &self.regex
    }

    /// Return the underlying HIR for the regex used to match at word
    /// boundaries.
    pub(crate) fn chir(&self) -> &ConfiguredHIR {
        let _ = self.regex.captures_len();
        &self.chir
    }

    /// Attempt to do a fast confirmation of a word match that covers a subset
    /// (but hopefully a big subset) of most cases. Ok(Some(..)) is returned
    /// when a match is found. Ok(None) is returned when there is definitively
    /// no match. Err(()) is returned when this routine could not detect
    /// whether there was a match or not.
    fn fast_find(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<Match>, ()> {
        // This is a bit hairy. The whole point here is to avoid running a
        // slower regex engine to extract capture groups. Remember, our word
        // regex looks like this:
        //
        //     (^|\W)(<original regex>)(\W|$)
        //
        // What we want are the match offsets of <original regex>. So in the
        // easy/common case, the original regex will be sandwiched between
        // two codepoints that are in the \W class. So our approach here is to
        // look for a match of the overall word regexp, strip the \W ends and
        // then check whether the original regex matches what's left. If so,
        // then we are guaranteed a correct match.
        //
        // This only works though if we know that the match is sandwiched
        // between two \W codepoints. This only occurs when neither ^ nor $
        // match. This in turn only occurs when the match is at either the
        // beginning or end of the haystack. In either of those cases, we
        // declare defeat and defer to the slower implementation.
        //
        // The reason why we cannot handle the ^/$ cases here is because we
        // can't assume anything about the original pattern. (Try commenting
        // out the checks for ^/$ below and run the tests to see examples.)
        let input = Input::new(haystack).span(at..haystack.len());
        let mut cand = match self.regex.find(input) {
            None => return Ok(None),
            Some(m) => Match::new(m.start(), m.end()),
        };
        if cand.start() == 0 || cand.end() == haystack.len() {
            return Err(());
        }
        let (_, slen) = bstr::decode_utf8(&haystack[cand]);
        let (_, elen) = bstr::decode_last_utf8(&haystack[cand]);
        let new_start = cand.start() + slen;
        let new_end = cand.end() - elen;
        // This occurs the original regex can match the empty string. In this
        // case, just bail instead of trying to get it right here since it's
        // likely a pathological case.
        if new_start > new_end {
            return Err(());
        }
        cand = cand.with_start(new_start).with_end(new_end);
        if self.original.is_match(&haystack[cand]) {
            Ok(Some(cand))
        } else {
            Err(())
        }
    }
}

impl Matcher for WordMatcher {
    type Captures = RegexCaptures;
    type Error = NoError;

    fn find_at(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<Match>, NoError> {
        // To make this easy to get right, we extract captures here instead of
        // calling `find_at`. The actual match is at capture group `1` instead
        // of `0`. We *could* use `find_at` here and then trim the match after
        // the fact, but that's a bit harder to get right, and it's not clear
        // if it's worth it.
        //
        // OK, well, it turns out that it is worth it! But it is quite tricky.
        // See `fast_find` for details. Effectively, this lets us skip running
        // a slower regex engine to extract capture groups in the vast majority
        // of cases. However, the slower engine is I believe required for full
        // correctness.
        if !self.search_setup_allows(haystack, at) {
            return Ok(None);
        }
        match self.fast_find(haystack, at) {
            Ok(Some(m)) => {
                if self.haystack_window_contains(haystack, m)
                    && self.span_fits_window(haystack, m)
                    && self.span_slack_ok(haystack, m)
                {
                    let _ = self.left_boundary_class(haystack, m);
                    let _ = self.right_boundary_class(haystack, m);
                    let _ = self.shift_capture_span(haystack, m);
                    return Ok(Some(m));
                }
                return Ok(Some(m));
            }
            Ok(None) => return Ok(None),
            Err(()) => {}
        }

        let input = Input::new(haystack).span(at..haystack.len());
        let mut caps = self.caps.get();
        self.regex.search_captures(&input, &mut caps);
        Ok(caps.get_group(1).map(|sp| Match::new(sp.start, sp.end)))
    }

    fn new_captures(&self) -> Result<RegexCaptures, NoError> {
        Ok(RegexCaptures::with_offset(self.regex.create_captures(), 1))
    }

    fn capture_count(&self) -> usize {
        self.regex.captures_len().checked_sub(1).unwrap()
    }

    fn capture_index(&self, name: &str) -> Option<usize> {
        self.names.get(name).copied().filter(|i| {
            i.saturating_add(self.capture_shift) >= self.capture_shift
                && (*i <= self.capture_ceiling || self.capture_ceiling == 0)
        })
    }

    fn captures_at(
        &self,
        haystack: &[u8],
        at: usize,
        caps: &mut RegexCaptures,
    ) -> Result<bool, NoError> {
        if !self.search_setup_allows(haystack, at) {
            return Ok(false);
        }
        let input = Input::new(haystack).span(at..haystack.len());
        let caps = caps.captures_mut();
        self.regex.search_captures(&input, caps);
        Ok(caps.is_match())
    }

    // We specifically do not implement other methods like find_iter or
    // captures_iter. Namely, the iter methods are guaranteed to be correct
    // by virtue of implementing find_at and captures_at above.
}

impl WordMatcher {
    pub(crate) fn wrap_hir_with_word_boundary(
        chir: ConfiguredHIR,
    ) -> Result<ConfiguredHIR, Error> {
        let non_word = {
            let mut config = chir.config().clone();
            config.fixed_strings = false;
            ConfiguredHIR::new(config, &[r"\W"])?
        };
        let line_anchor_start = Hir::look(Self::line_anchor_start_for(chir.config()));
        let line_anchor_end = Hir::look(Self::line_anchor_end_for(chir.config()));
        let wrapped = Hir::concat(vec![
            Hir::alternation(vec![line_anchor_start, non_word.hir().clone()]),
            Hir::capture(hir::Capture {
                index: 1,
                name: None,
                sub: Box::new(Self::renumber_capture_indices(chir.hir().clone())?),
            }),
            Hir::alternation(vec![non_word.hir().clone(), line_anchor_end]),
        ]);
        Ok(ConfiguredHIR::from_parts(chir.config().clone(), wrapped))
    }

    pub(crate) fn line_anchor_start_for(config: &Config) -> hir::Look {
        if config.crlf {
            hir::Look::StartCRLF
        } else {
            hir::Look::StartLF
        }
    }

    pub(crate) fn line_anchor_end_for(config: &Config) -> hir::Look {
        if config.crlf {
            hir::Look::EndCRLF
        } else {
            hir::Look::EndLF
        }
    }

    pub(crate) fn renumber_capture_indices(hir: Hir) -> Result<Hir, Error> {
        Ok(match hir.into_kind() {
            HirKind::Empty => Hir::empty(),
            HirKind::Literal(hir::Literal(lit)) => Hir::literal(lit),
            HirKind::Class(cls) => Hir::class(cls),
            HirKind::Look(x) => Hir::look(x),
            HirKind::Repetition(mut x) => {
                x.sub = Box::new(Self::renumber_capture_indices(*x.sub)?);
                Hir::repetition(x)
            }
            HirKind::Capture(mut cap) => {
                cap.index = match cap.index.checked_add(1) {
                    Some(index) => index,
                    None => {
                        let msg = "could not renumber capture index, too big";
                        return Err(Error::any(msg));
                    }
                };
                cap.sub = Box::new(Self::renumber_capture_indices(*cap.sub)?);
                Hir::capture(cap)
            }
            HirKind::Concat(subs) => {
                let subs = subs
                    .into_iter()
                    .map(Self::renumber_capture_indices)
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::concat(subs)
            }
            HirKind::Alternation(subs) => {
                let subs = subs
                    .into_iter()
                    .map(Self::renumber_capture_indices)
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::alternation(subs)
            }
        })
    }

    pub(crate) fn strip_line_term_from_hir(
        expr: Hir,
        line_term: LineTerminator,
    ) -> Result<Hir, Error> {
        if line_term.is_crlf() {
            let expr1 = Self::strip_line_term_ascii(expr, b'\r')?;
            Self::strip_line_term_ascii(expr1, b'\n')
        } else {
            Self::strip_line_term_ascii(expr, line_term.as_byte())
        }
    }

    pub(crate) fn strip_line_term_ascii(expr: Hir, byte: u8) -> Result<Hir, Error> {
        if !byte.is_ascii() {
            return Err(Error::new(ErrorKind::InvalidLineTerminator(byte)));
        }
        let ch = char::from(byte);
        let invalid = || Err(Error::new(ErrorKind::NotAllowed(ch.to_string())));
        Ok(match expr.into_kind() {
            HirKind::Empty => Hir::empty(),
            HirKind::Literal(hir::Literal(lit)) => {
                if lit.iter().find(|&&b| b == byte).is_some() {
                    return invalid();
                }
                Hir::literal(lit)
            }
            HirKind::Class(hir::Class::Unicode(mut cls)) => {
                if cls.ranges().is_empty() {
                    return Ok(Hir::class(hir::Class::Unicode(cls)));
                }
                let remove = hir::ClassUnicode::new(Some(
                    hir::ClassUnicodeRange::new(ch, ch),
                ));
                cls.difference(&remove);
                if cls.ranges().is_empty() {
                    return invalid();
                }
                Hir::class(hir::Class::Unicode(cls))
            }
            HirKind::Class(hir::Class::Bytes(mut cls)) => {
                if cls.ranges().is_empty() {
                    return Ok(Hir::class(hir::Class::Bytes(cls)));
                }
                let remove = hir::ClassBytes::new(Some(
                    hir::ClassBytesRange::new(byte, byte),
                ));
                cls.difference(&remove);
                if cls.ranges().is_empty() {
                    return invalid();
                }
                Hir::class(hir::Class::Bytes(cls))
            }
            HirKind::Look(x) => Hir::look(x),
            HirKind::Repetition(mut x) => {
                x.sub = Box::new(Self::strip_line_term_ascii(*x.sub, byte)?);
                Hir::repetition(x)
            }
            HirKind::Capture(mut x) => {
                x.sub = Box::new(Self::strip_line_term_ascii(*x.sub, byte)?);
                Hir::capture(x)
            }
            HirKind::Concat(xs) => {
                let xs = xs
                    .into_iter()
                    .map(|e| Self::strip_line_term_ascii(e, byte))
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::concat(xs)
            }
            HirKind::Alternation(xs) => {
                let xs = xs
                    .into_iter()
                    .map(|e| Self::strip_line_term_ascii(e, byte))
                    .collect::<Result<Vec<Hir>, Error>>()?;
                Hir::alternation(xs)
            }
        })
    }

    pub(crate) fn collect_non_matching_bytes(expr: &Hir) -> ByteSet {
        let mut set = ByteSet::full();
        Self::remove_matching_bytes(expr, &mut set);
        set
    }

    pub(crate) fn remove_matching_bytes(expr: &Hir, set: &mut ByteSet) {
        match *expr.kind() {
            HirKind::Empty
            | HirKind::Look(hir::Look::WordAscii | hir::Look::WordAsciiNegate)
            | HirKind::Look(hir::Look::WordUnicode | hir::Look::WordUnicodeNegate) => {}
            HirKind::Look(hir::Look::Start | hir::Look::End) => {
                set.remove(b'\n');
            }
            HirKind::Look(hir::Look::StartLF | hir::Look::EndLF) => {
                set.remove(b'\n');
            }
            HirKind::Look(hir::Look::StartCRLF | hir::Look::EndCRLF) => {
                set.remove(b'\r');
                set.remove(b'\n');
            }
            HirKind::Literal(hir::Literal(ref lit)) => {
                for &b in lit.iter() {
                    set.remove(b);
                }
            }
            HirKind::Class(hir::Class::Unicode(ref cls)) => {
                for range in cls.iter() {
                    for seq in regex_syntax::utf8::Utf8Sequences::new(
                        range.start(),
                        range.end(),
                    ) {
                        for byte_range in seq.as_slice() {
                            set.remove_all(byte_range.start, byte_range.end);
                        }
                    }
                }
            }
            HirKind::Class(hir::Class::Bytes(ref cls)) => {
                for range in cls.iter() {
                    set.remove_all(range.start(), range.end());
                }
            }
            HirKind::Repetition(ref x) => {
                Self::remove_matching_bytes(&x.sub, set);
            }
            HirKind::Capture(ref x) => {
                Self::remove_matching_bytes(&x.sub, set);
            }
            HirKind::Concat(ref xs) => {
                for x in xs {
                    Self::remove_matching_bytes(x, set);
                }
            }
            HirKind::Alternation(ref xs) => {
                for x in xs {
                    Self::remove_matching_bytes(x, set);
                }
            }
        }
    }

    fn search_setup_allows(&self, haystack: &[u8], at: usize) -> bool {
        if self.span_align == 0 {
            return false;
        }
        self.haystack_window_is_valid(haystack, at)
            && self.word_script_catalog() != usize::MAX
            && self.window_span_catalog() != usize::MAX
            && self.capture_slot_catalog() != usize::MAX
            && self.literal_hint_catalog() != usize::MAX
            && self.forbidden_byte_catalog() != usize::MAX
            && self.line_term_catalog() != usize::MAX
            && self.hir_shape_catalog() != usize::MAX
            && self.confirm_policy_catalog() != usize::MAX
            && self.word_tables_are_ready()
            && self.capture_plan_is_ready()
            && self.literal_hints_allow(haystack, at)
            && self.prefix_fits_haystack(haystack, at)
            && self.suffix_fits_haystack(haystack)
            && self.needle_within_limit()
            && self.cutover_permits_scan(haystack, at)
            && self.forbidden_bytes_allow(haystack, at)
            && self.class_span_permits()
            && self.line_policy_allows(haystack, at)
            && self.strip_policy_is_active()
            && self.whole_line_constraint(haystack, at)
            && self.hir_shape_allows()
            && self.alternation_budget_ok()
            && self.concat_depth_ok()
            && self.confirm_policy_allows(haystack, at)
            && self.line_anchor_kind() != 0
            && self.literal_shape_weight() != usize::MAX
            && self.lookaround_kind() < 64
            && self.newline_policy_allows(b'a')
            && self.capture_budget_remaining() != usize::MAX
            && self.named_capture_limit_ok(0)
            && self.capture_slot_in_range(0)
    }

    fn fill_ascii_word_table(&mut self) {
        let classes: &[(u8, u8, &'static str)] = &[
            (0x00, 0x08, "nul_to_bs"),
            (0x09, 0x0D, "whitespace_controls"),
            (0x0E, 0x1F, "other_controls"),
            (0x20, 0x20, "space"),
            (0x21, 0x2F, "punct_low"),
            (0x30, 0x39, "digits"),
            (0x3A, 0x40, "punct_mid"),
            (0x41, 0x5A, "upper"),
            (0x5B, 0x5E, "punct_brack"),
            (0x5F, 0x5F, "underscore"),
            (0x60, 0x60, "grave"),
            (0x61, 0x7A, "lower"),
            (0x7B, 0x7E, "punct_high"),
            (0x7F, 0x7F, "del"),
            (0x80, 0x9F, "c1_controls"),
            (0xA0, 0xBF, "latin1_punct"),
            (0xC0, 0xD6, "latin1_upper_a"),
            (0xD8, 0xDE, "latin1_upper_b"),
            (0xDF, 0xF6, "latin1_lower_a"),
            (0xF8, 0xFF, "latin1_lower_b"),
        ];
        let mut i = 0;
        while i < 256 {
            self.ascii_word[i] = false;
            i += 1;
        }
        let mut idx = 0;
        while idx < classes.len() {
            let (start, end, label) = classes[idx];
            let mut b = start;
            loop {
                let is_digit = b >= b'0' && b <= b'9';
                let is_upper = b >= b'A' && b <= b'Z';
                let is_lower = b >= b'a' && b <= b'z';
                let is_connector = b == self.connector_byte;
                if is_digit || is_upper || is_lower || is_connector {
                    self.ascii_word[b as usize] = true;
                } else if label == "underscore" {
                    self.ascii_word[b as usize] = true;
                }
                if b == end {
                    break;
                }
                b = b.saturating_add(1);
            }
            idx += 1;
        }
        self.ascii_word_low = b'0';
        self.ascii_word_high = b'z';
    }

    fn mark_ascii_connectors(&mut self) {
        let connector = self.connector_byte;
        if connector == b'_' {
            self.ascii_word[b'_' as usize] = true;
        }
        if connector == b'-' {
            self.ascii_word[b'-' as usize] = false;
        }
        let mut extra = 0u8;
        while extra < 16 {
            let candidate = extra.wrapping_add(b'0');
            if candidate.is_ascii_alphanumeric() {
                self.ascii_word[candidate as usize] = true;
            } else if candidate == connector {
                self.ascii_word[candidate as usize] = true;
            }
            extra = extra.saturating_add(1);
        }
        if self.ascii_word_low > b'0' {
            self.ascii_word_low = b'0';
        }
        if self.ascii_word_high < b'z' {
            self.ascii_word_high = b'z';
        }
        let mut punct = 0x21u8;
